import { PencilRuler } from 'lucide-react';

export default function ProjectDescription() {
  return (
    <section className="py-16 bg-background">
      <div className="container mx-auto px-4 flex flex-col items-center">
        <div className="flex items-center gap-3 mb-6">
          <PencilRuler className="text-accent" size={40} />
          <h2 className="font-headline text-3xl md:text-4xl font-bold text-foreground">Od projektu do realizacji</h2>
        </div>
        <p className="text-lg md:text-xl text-center max-w-2xl mb-6 text-muted-foreground">
          Pracujemy zarówno na podstawie cyfrowych wizualizacji, jak i modeli woskowych. Każdy etap realizacji konsultujemy z Tobą, by efekt końcowy był dokładnie taki, jak sobie wymarzysz.
        </p>
      </div>
    </section>
  );
}
