export default function CreativeProcess() {
  return (
    <section className="py-16 bg-secondary">
      <div className="container mx-auto px-4 flex flex-col items-center">
        <Sparkles className="text-accent mb-4" size={48} />
        <h2 className="text-3xl md:text-4xl font-headline font-bold text-center mb-4 text-foreground">
          Proces twórczy
        </h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 max-w-5xl mx-auto">
          {steps.map((step, i) => (
            <Card key={i} className="flex flex-col items-center py-8 px-6 shadow-lg bg-background/80">
              <step.icon className="text-accent mb-4" size={40} />
              <div className="text-2xl font-bold mb-2 text-foreground">{i + 1}. {step.title}</div>
              <CardContent className="text-muted-foreground text-center text-base px-0">
                {step.desc}
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
}

import { Sparkles, User, PenTool, Gem, Hammer, Package } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';

const steps = [
  {
    icon: User,
    title: 'Konsultacja',
    desc: 'Poznajemy Twoje oczekiwania i inspiracje podczas indywidualnej rozmowy.',
  },
  {
    icon: PenTool,
    title: 'Projekt',
    desc: 'Tworzymy cyfrowy projekt lub model woskowy do Twojej akceptacji.',
  },
  {
    icon: Gem,
    title: 'Materiały',
    desc: 'Wspólnie wybieramy materiały i kamienie szlachetne najwyższej jakości.',
  },
  {
    icon: Hammer,
    title: 'Ręczne wykonanie',
    desc: 'Biżuteria powstaje ręcznie w naszej wrocławskiej pracowni.',
  },
  {
    icon: Package,
    title: 'Odbiór',
    desc: 'Gotowe dzieło odbierasz osobiście lub wysyłamy je pod wskazany adres.',
  },
];
